fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // Ensure the inputs have the same length
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );

    // Compute element-wise products
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| x * y)
        .collect()
}

